use std::collections::BTreeSet;

use tree_sitter::{Node, Parser};

use super::language::Language;

#[derive(Debug, Clone)]
pub struct RawReference {
    pub target_name: String,
    pub kind: String,
    pub line: usize,
    pub edge_source: String,
    pub confidence: f64,
}

pub fn extract_references(
    content: &str,
    language: Language,
    candidate_names: &BTreeSet<String>,
) -> Vec<RawReference> {
    if candidate_names.is_empty() {
        return Vec::new();
    }

    if language.is_code()
        && let Some(references) = extract_tree_sitter_references(content, language, candidate_names)
    {
        return references;
    }

    let scan_content;
    let content = if language.is_code() {
        scan_content = strip_comments_and_strings(content, language);
        scan_content.as_str()
    } else {
        content
    };
    extract_references_fallback(content, candidate_names)
}

fn extract_references_fallback(
    content: &str,
    candidate_names: &BTreeSet<String>,
) -> Vec<RawReference> {
    let mut references = Vec::new();
    let mut seen = BTreeSet::new();

    for (line_index, line) in content.lines().enumerate() {
        let trimmed = line.trim_start();
        if trimmed.starts_with("//")
            || trimmed.starts_with('#')
            || trimmed.starts_with("/*")
            || trimmed.starts_with('*')
        {
            continue;
        }

        for name in candidate_names_in_line(line, candidate_names) {
            if is_definition_line(line, name) {
                continue;
            }

            if let Some(kind) = reference_kind(line, name) {
                let line_number = line_index + 1;
                if seen.insert((line_number, name.to_string(), kind.clone())) {
                    references.push(RawReference {
                        target_name: name.to_string(),
                        kind,
                        line: line_number,
                        edge_source: "heuristic".to_string(),
                        confidence: 0.45,
                    });
                }
            }
        }
    }

    references
}

fn candidate_names_in_line<'a>(line: &str, candidate_names: &'a BTreeSet<String>) -> Vec<&'a str> {
    let mut names = Vec::new();
    let mut seen = BTreeSet::new();
    let mut token_start = None;

    for (index, character) in line
        .char_indices()
        .chain(std::iter::once((line.len(), ' ')))
    {
        if is_identifier_character(character) {
            token_start.get_or_insert(index);
            continue;
        }

        let Some(start) = token_start.take() else {
            continue;
        };
        let token = &line[start..index];
        if token.len() < 3 {
            continue;
        }
        if let Some(candidate) = candidate_names.get(token)
            && seen.insert(candidate.as_str())
        {
            names.push(candidate.as_str());
        }
    }

    names
}

fn is_identifier_character(character: char) -> bool {
    character.is_ascii_alphanumeric() || character == '_' || character == '$'
}

fn extract_tree_sitter_references(
    content: &str,
    language: Language,
    candidate_names: &BTreeSet<String>,
) -> Option<Vec<RawReference>> {
    let parser_language = parser_language(language)?;
    let mut parser = Parser::new();
    parser.set_language(&parser_language).ok()?;
    let tree = parser.parse(content, None)?;
    if tree.root_node().has_error() {
        return None;
    }

    let mut references = Vec::new();
    let mut seen = BTreeSet::new();
    collect_reference_nodes(
        tree.root_node(),
        content,
        candidate_names,
        &mut references,
        &mut seen,
    );
    Some(references)
}

fn parser_language(language: Language) -> Option<tree_sitter::Language> {
    match language {
        Language::JavaScript => Some(tree_sitter_javascript::LANGUAGE.into()),
        Language::TypeScript => Some(tree_sitter_typescript::LANGUAGE_TYPESCRIPT.into()),
        Language::Python => Some(tree_sitter_python::LANGUAGE.into()),
        Language::Rust => Some(tree_sitter_rust::LANGUAGE.into()),
        Language::Php
        | Language::Go
        | Language::Java
        | Language::CSharp
        | Language::C
        | Language::Cpp
        | Language::Ruby
        | Language::Kotlin
        | Language::Swift
        | Language::Scala
        | Language::Dart
        | Language::Lua
        | Language::Shell => None,
        Language::Markdown | Language::Json | Language::Toml | Language::Yaml | Language::Text => {
            None
        }
    }
}

fn collect_reference_nodes(
    node: Node<'_>,
    content: &str,
    candidate_names: &BTreeSet<String>,
    references: &mut Vec<RawReference>,
    seen: &mut BTreeSet<(usize, String, String)>,
) {
    if is_reference_identifier(node)
        && !is_definition_identifier(node)
        && !is_import_identifier(node)
        && let Ok(name) = node.utf8_text(content.as_bytes())
        && name.len() >= 3
        && candidate_names.contains(name)
    {
        let line_number = node.start_position().row + 1;
        let kind = reference_kind_after_node(content, node);
        if seen.insert((line_number, name.to_string(), kind.clone())) {
            references.push(RawReference {
                target_name: name.to_string(),
                kind,
                line: line_number,
                edge_source: "tree_sitter".to_string(),
                confidence: 0.8,
            });
        }
    }

    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        collect_reference_nodes(child, content, candidate_names, references, seen);
    }
}

fn is_reference_identifier(node: Node<'_>) -> bool {
    matches!(
        node.kind(),
        "identifier"
            | "property_identifier"
            | "field_identifier"
            | "shorthand_property_identifier"
            | "type_identifier"
    )
}

fn is_definition_identifier(node: Node<'_>) -> bool {
    let Some(parent) = node.parent() else {
        return false;
    };
    if !matches!(
        parent.kind(),
        "function_declaration"
            | "generator_function_declaration"
            | "class_declaration"
            | "method_definition"
            | "interface_declaration"
            | "type_alias_declaration"
            | "variable_declarator"
            | "function_definition"
            | "class_definition"
            | "function_item"
            | "struct_item"
            | "enum_item"
            | "trait_item"
            | "impl_item"
            | "const_item"
            | "mod_item"
    ) {
        return false;
    }

    ["name", "pattern", "type"]
        .into_iter()
        .filter_map(|field| parent.child_by_field_name(field))
        .any(|child| child.start_byte() == node.start_byte() && child.end_byte() == node.end_byte())
}

