pub(crate) fn stable_content_hash(bytes: &[u8]) -> String {
    let mut hash = 0xcbf29ce484222325_u64;
    for byte in bytes {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x100000001b3);
    }
    format!("fnv1a64:{hash:016x}")
}

fn module_path(path: &Path) -> String {
    path.parent().map(path_to_string).unwrap_or_default()
}

pub(crate) fn is_test_file(path: &str) -> bool {
    let lower = path.replace('\\', "/").to_ascii_lowercase();
    // Match both nested (`src/tests/`, `src/test/`) and top-level (`tests/`,
    // `test/`) test dirs; paths are repo-relative with no leading slash, so a
    // `/tests/` check alone misses the common top-level `tests/` and
    // `__tests__/` convention.
    lower.contains("/__tests__/")
        || lower.starts_with("__tests__/")
        || lower.contains("/test/")
        || lower.starts_with("test/")
        || lower.contains("/tests/")
        || lower.starts_with("tests/")
        || lower.contains("_test.")
        || lower.contains(".test.")
        || lower.contains(".spec.")
        || lower.ends_with("_test.rs")
}

fn is_config_file(path: &str) -> bool {
    let lower = path.to_ascii_lowercase();
    let file = lower.rsplit('/').next().unwrap_or(lower.as_str());
    lower.starts_with(".github/workflows/")
        || file.contains("config")
        || matches!(
            file,
            "build.rs"
                | "cargo.toml"
                | "package.json"
                | "pyproject.toml"
                | "requirements.txt"
                | "rust-toolchain.toml"
                | "rustfmt.toml"
                | "clippy.toml"
        )
}

fn content_terms(content: &str, language: Language) -> Vec<String> {
    let code_content;
    let content = if language.is_code() {
        code_content = strip_comment_only_lines(content);
        code_content.as_str()
    } else {
        content
    };
    let mut counts = BTreeMap::new();
    for token in tokenize_content(content) {
        *counts.entry(token).or_insert(0usize) += 1;
    }

    let mut ranked_terms: Vec<(String, usize)> = counts.into_iter().collect();
    ranked_terms.sort_by(|left, right| right.1.cmp(&left.1).then(left.0.cmp(&right.0)));
    ranked_terms
        .into_iter()
        .take(if language.is_code() { 80 } else { 120 })
        .map(|(term, _)| term)
        .collect()
}

fn strip_comment_only_lines(content: &str) -> String {
    content
        .lines()
        .filter(|line| {
            let trimmed = line.trim_start();
            !(trimmed.starts_with("//")
                || trimmed.starts_with('#')
                || trimmed.starts_with("/*")
                || trimmed.starts_with('*'))
        })
        .collect::<Vec<_>>()
        .join("\n")
}

fn tokenize_content(input: &str) -> Vec<String> {
    const STOP_WORDS: &[&str] = &[
        "a", "an", "and", "are", "as", "at", "be", "by", "for", "from", "how", "in", "is", "it",
        "of", "on", "or", "that", "the", "this", "to", "with",
    ];

    split_camel_case(input)
        .split(|character: char| !character.is_ascii_alphanumeric())
        .map(|token| token.trim().to_ascii_lowercase())
        .filter(|token| token.len() > 1)
        .filter(|token| !STOP_WORDS.contains(&token.as_str()))
        .collect()
}

fn split_camel_case(input: &str) -> String {
    let mut output = String::with_capacity(input.len() + 8);
    let mut previous_lowercase = false;

    for character in input.chars() {
        if previous_lowercase && character.is_ascii_uppercase() {
            output.push(' ');
        }
        previous_lowercase = character.is_ascii_lowercase() || character.is_ascii_digit();
        output.push(character);
    }

    output
}

fn resolve_import(
    root: &Path,
    source: &Path,
    language: Language,
    imported: &str,
) -> Option<String> {
    match language {
        Language::TypeScript | Language::JavaScript => {
            if !imported.starts_with('.') {
                return None;
            }
            let base = source.parent().unwrap_or_else(|| Path::new(""));
            let candidate = normalize_relative(base.join(imported));
            let extensions: &[&str] = if language == Language::TypeScript {
                &["ts", "tsx", "js", "jsx"]
            } else {
                &["js", "jsx", "ts", "tsx"]
            };
            resolve_candidate(root, &candidate, extensions).map(|path| path_to_string(&path))
        }
        Language::Python => resolve_python_import(root, source, imported),
        Language::Rust => resolve_rust_import(root, source, imported),
        Language::Php => resolve_relative_import(root, source, imported, &["php", "phtml"]),
        Language::Ruby => resolve_relative_import(root, source, imported, &["rb"]),
        Language::Dart => resolve_relative_import(root, source, imported, &["dart"]),
        Language::Shell => resolve_relative_import(root, source, imported, &["sh", "bash", "zsh"]),
        Language::C => resolve_relative_import(root, source, imported, &["h", "c"]),
        Language::Cpp => resolve_relative_import(
            root,
            source,
            imported,
            &["hpp", "hh", "hxx", "h", "cpp", "cc", "cxx"],
        ),
        Language::Go
        | Language::Java
        | Language::CSharp
        | Language::Kotlin
        | Language::Swift
        | Language::Scala
        | Language::Lua => None,
        Language::Markdown | Language::Json | Language::Toml | Language::Yaml | Language::Text => {
            None
        }
    }
}

fn resolve_relative_import(
    root: &Path,
    source: &Path,
    imported: &str,
    extensions: &[&str],
) -> Option<String> {
    let imported = imported
        .trim()
        .trim_end_matches(';')
        .trim_matches(['"', '\'', '<', '>']);
    if imported.is_empty() || !(imported.starts_with('.') || imported.contains('/')) {
        return None;
    }
    let base = source.parent().unwrap_or_else(|| Path::new(""));
    let candidate = normalize_relative(base.join(imported));
    resolve_candidate(root, &candidate, extensions).map(|path| path_to_string(&path))
}

fn resolve_candidate(root: &Path, candidate: &Path, extensions: &[&str]) -> Option<PathBuf> {
    if root.join(candidate).is_file() {
        return Some(candidate.to_path_buf());
    }

    for extension in extensions {
        let with_extension = candidate.with_extension(extension);
        if root.join(&with_extension).is_file() {
            return Some(with_extension);
        }
    }

    for extension in extensions {
        let index_file = candidate.join(format!("index.{extension}"));
        if root.join(&index_file).is_file() {
            return Some(index_file);
        }
    }

    if extensions.contains(&"py") {
        let init_file = candidate.join("__init__.py");
        if root.join(&init_file).is_file() {
            return Some(init_file);
        }
    }

    None
}

fn normalize_relative(path: PathBuf) -> PathBuf {
    let mut normalized = PathBuf::new();
    for component in path.components() {
        match component {
            std::path::Component::CurDir => {}
            std::path::Component::ParentDir => {
                normalized.pop();
            }
            other => normalized.push(other.as_os_str()),
        }
    }
    normalized
}

fn resolve_python_import(root: &Path, source: &Path, imported: &str) -> Option<String> {
    let raw_imported = imported.trim();
    let imported = raw_imported.trim_start_matches('.');
    if imported.is_empty() {
        return None;
    }

    let module_path = PathBuf::from(imported.replace('.', "/"));
    let mut candidates = vec![module_path.clone(), PathBuf::from("src").join(&module_path)];

    if let Some(top_level) = source.components().next() {
        candidates.push(PathBuf::from(top_level.as_os_str()).join(&module_path));
    }

    if raw_imported.starts_with('.') {
        let base = source.parent().unwrap_or_else(|| Path::new(""));
        candidates.push(normalize_relative(base.join(&module_path)));
    }

    candidates.into_iter().find_map(|candidate| {
        resolve_candidate(root, &candidate, &["py"]).map(|path| path_to_string(&path))
    })
}

fn resolve_rust_import(root: &Path, source: &Path, imported: &str) -> Option<String> {
    let imported = imported
        .trim()
        .trim_end_matches(';')
        .split_once(" as ")
        .map(|(path, _)| path)
        .unwrap_or(imported)
        .trim();
    let imported = imported
        .split_once('{')
        .map(|(prefix, _)| prefix.trim_end_matches("::"))
        .unwrap_or(imported);
    let parts: Vec<&str> = imported
        .split("::")
        .map(str::trim)
        .filter(|part| !part.is_empty())
        .collect();
    if parts.is_empty() {
        return None;
    }

    let base = rust_import_base(source, parts[0]);
    let mut module_parts = match parts[0] {
        "crate" | "self" | "super" => parts[1..].to_vec(),
        _ => parts.clone(),
    };
    if module_parts.is_empty() {
        return None;

fn is_import_identifier(node: Node<'_>) -> bool {
    let mut current = node.parent();
    while let Some(node) = current {
        if matches!(
            node.kind(),
            "import_statement"
                | "import_specifier"
                | "import_clause"
                | "import_from_statement"
                | "aliased_import"
                | "use_declaration"
                | "scoped_use_list"
                | "use_as_clause"
        ) {
            return true;
        }
        current = node.parent();
    }
    false
}

fn reference_kind_after_node(content: &str, node: Node<'_>) -> String {
    let after = &content[node.end_byte()..];
    let is_call = after
        .chars()
        .find(|character| !character.is_whitespace())
        .is_some_and(|character| character == '(');

    if is_call { "call" } else { "reference" }.to_string()
}

fn reference_kind(line: &str, name: &str) -> Option<String> {
    let start = find_identifier(line, name)?;
    let after = &line[start + name.len()..];
    let is_call = after
        .chars()
        .find(|character| !character.is_whitespace())
        .is_some_and(|character| character == '(');

    Some(if is_call { "call" } else { "reference" }.to_string())
}

fn find_identifier(line: &str, name: &str) -> Option<usize> {
    let mut offset = 0;
    while let Some(relative_start) = line[offset..].find(name) {
        let start = offset + relative_start;
        let end = start + name.len();
        if is_boundary(line[..start].chars().next_back()) && is_boundary(line[end..].chars().next())
        {
            return Some(start);
        }
        offset = end;
    }

    None
}

fn is_boundary(character: Option<char>) -> bool {
    character.is_none_or(|character| {
        !(character.is_ascii_alphanumeric() || character == '_' || character == '$')
    })
}

fn is_definition_line(line: &str, name: &str) -> bool {
    let trimmed = line.trim_start();
    let prefixes = [
        format!("function {name}"),
        format!("async function {name}"),
        format!("export function {name}"),
        format!("export async function {name}"),
        format!("class {name}"),
        format!("export class {name}"),
        format!("interface {name}"),
        format!("export interface {name}"),
        format!("type {name}"),
        format!("export type {name}"),
        format!("const {name}"),
        format!("export const {name}"),
        format!("let {name}"),
        format!("export let {name}"),
        format!("var {name}"),
        format!("export var {name}"),
        format!("def {name}"),
        format!("async def {name}"),
        format!("class {name}"),
        format!("fn {name}"),
        format!("pub fn {name}"),
        format!("struct {name}"),
        format!("pub struct {name}"),
        format!("enum {name}"),
        format!("pub enum {name}"),
        format!("trait {name}"),
        format!("pub trait {name}"),
    ];

    prefixes.iter().any(|prefix| trimmed.starts_with(prefix))
}

fn strip_comments_and_strings(content: &str, language: Language) -> String {
    let chars: Vec<char> = content.chars().collect();
    let mut output = String::with_capacity(content.len());
    let mut index = 0;
    let mut state = StripState::Normal;

    while index < chars.len() {
        let character = chars[index];
        match state {
            StripState::Normal => {
                if let Some(length) = line_comment_len(&chars, index, language) {
                    for _ in 0..length {
                        output.push(' ');
                    }
                    index += length;
                    state = StripState::LineComment;
                } else if let Some(length) = block_comment_len(&chars, index, language) {
                    for _ in 0..length {
                        output.push(' ');
                    }
                    index += length;
                    state = StripState::BlockComment;
                } else if is_string_quote(character, language) {
                    output.push(' ');
                    index += 1;
                    state = StripState::String {
                        quote: character,
                        escaped: false,
                    };
                } else {
                    output.push(character);
                    index += 1;
                }
            }
            StripState::LineComment => {
                if character == '\n' {
                    output.push('\n');
                    state = StripState::Normal;
                } else {
                    output.push(' ');
                }
                index += 1;
            }
            StripState::BlockComment => {
                if character == '*' && chars.get(index + 1) == Some(&'/') {
                    output.push(' ');
                    output.push(' ');
                    index += 2;
                    state = StripState::Normal;
                } else {
                    output.push(if character == '\n' { '\n' } else { ' ' });
                    index += 1;
                }
            }
            StripState::String { quote, escaped } => {
                output.push(if character == '\n' { '\n' } else { ' ' });
                index += 1;
                state = if escaped {
                    StripState::String {
                        quote,
                        escaped: false,
                    }
                } else if character == '\\' {
                    StripState::String {
                        quote,
                        escaped: true,
                    }
                } else if character == quote {
                    StripState::Normal
                } else {
                    StripState::String {
                        quote,
                        escaped: false,
                    }
                };
            }
        }
    }

    output
}

#[derive(Debug, Clone, Copy)]
enum StripState {
    Normal,
    LineComment,
    BlockComment,
    String { quote: char, escaped: bool },
}

fn line_comment_len(chars: &[char], index: usize, language: Language) -> Option<usize> {
    match language {
        Language::Python | Language::Ruby | Language::Shell if chars[index] == '#' => Some(1),
        Language::Rust
        | Language::TypeScript
        | Language::JavaScript
        | Language::Php
        | Language::Go
        | Language::Java
        | Language::CSharp
        | Language::C
        | Language::Cpp
        | Language::Kotlin
        | Language::Swift
        | Language::Scala
        | Language::Dart
        | Language::Lua => (chars[index] == '/' && chars.get(index + 1) == Some(&'/')).then_some(2),
        Language::Markdown | Language::Json | Language::Toml | Language::Yaml | Language::Text => {
            None
        }
        _ => None,
    }
}

fn block_comment_len(chars: &[char], index: usize, language: Language) -> Option<usize> {
    (matches!(
        language,
        Language::Rust
            | Language::TypeScript
            | Language::JavaScript
            | Language::Php
            | Language::Go
            | Language::Java
            | Language::CSharp
            | Language::C
            | Language::Cpp
            | Language::Kotlin
            | Language::Swift
            | Language::Scala
            | Language::Dart
            | Language::Lua
    ) && chars[index] == '/'
        && chars.get(index + 1) == Some(&'*'))
    .then_some(2)
}

fn is_string_quote(character: char, language: Language) -> bool {
    match language {
        Language::TypeScript | Language::JavaScript | Language::Go | Language::Shell => {
            matches!(character, '\'' | '"' | '`')
        }
        Language::Python
        | Language::Rust
        | Language::Php
        | Language::Java
        | Language::CSharp
        | Language::C
        | Language::Cpp
        | Language::Ruby
        | Language::Kotlin
        | Language::Swift
        | Language::Scala
        | Language::Dart
        | Language::Lua => matches!(character, '\'' | '"'),
        Language::Markdown | Language::Json | Language::Toml | Language::Yaml | Language::Text => {
            false
        }
    }
}

